function sequenceRequest(){
 const q=request(),r={X:100,Y:200,Z:58.45,A:720,B:-3000};Object.assign(q,{scope:'contiguous-native-scrap-sequence-comparison-preview',targetSurface:'scrap-sequence-comparison',sequenceProtocol:'three-12-degree-sacrificial-then-three-6-degree-test-r2',expectedRaw:r,expectedDriver:{...r},xyClearanceRawZ:53.45,rawBounds:{X:{min:90,max:120},Y:{min:190,max:220},Z:{min:53.45,max:58.45},B:{min:-3400,max:-2900}},receivingProfile:{...q.receivingProfile,rawPose:{X:r.X,Y:r.Y,Z:r.Z,A:r.A}},previewStages:[]});
 q.expectedNativePoses={N1:{x:100,y:200,z:58.45},N2:{x:100,y:200,z:58.45},top:{},bottom:{}};
 let at={...r};function add(axis,value,extra={}){const target={...at,[axis]:value},d=value-at[axis];q.previewStages.push({axis,startRaw:at,targetRaw:target,speedFraction:axis==='B'?.05:1,...(axis==='B'?{gapEvidence:ev(),estimatedGapMm:.65,gapUncertaintyMm:.4}:{}),...extra});at=target;}
 function move(p){if(at.X!==p.X)add('X',p.X,at.Z===58.45?{wipeReview:true,wipeReviewEvidence:ev(),estimatedGapMm:.65,gapUncertaintyMm:.4}:{});if(at.Y!==p.Y)add('Y',p.Y,p.wipe?{wipeReview:true,wipeReviewEvidence:ev(),estimatedGapMm:.65,gapUncertaintyMm:.4}:{});}
 function stroke(d,dwell=0){add('B',at.B+d,dwell?{dwellMilliseconds:dwell}:{});}
 for(let i=0;i<3;i++)stroke(-20,i===2?2000:0);stroke(20,1000);move({X:101.5,Y:200});add('Z',53.45);move({X:102,Y:200});add('Z',58.45);stroke(-20,2000);stroke(2,500);add('Z',53.45);
 const deposits=(points,dose)=>points.forEach(p=>{if(at.X!==p.X)add('X',p.X);if(at.Y!==p.Y)add('Y',p.Y);add('Z',58.45);stroke(-2);if(dose===12){stroke(-6);stroke(-6,2000);}else stroke(-6,2000);stroke(2,500);add('Z',53.45);});
 deposits([{X:103,Y:201},{X:104,Y:201},{X:105,Y:201}],12);deposits([{X:103,Y:202},{X:104,Y:202},{X:105,Y:202}],6);stroke(20);stroke(20,2000);q.finalTargetRaw=at;return q;
}
test('dedicated scrap sequence scope admits exact 12 then 6 route and rejects altered order or >64 stages',()=>{
 const q=sequenceRequest();assert.equal(q.previewStages.length,54);B.validateBatch(q,1000,1,true);
 assert.equal(q.previewStages.filter(s=>s.axis==='B').reduce((n,s)=>n+Math.abs(s.targetRaw.B-s.startRaw.B),0),220);
 const wrong=clone(q),b=wrong.previewStages.filter(s=>s.axis==='B');const changed=b[8],shift=4;changed.targetRaw.B+=shift;let running={...wrong.expectedRaw};let bi=0;wrong.previewStages.forEach(s=>{const d=s.targetRaw[s.axis]-s.startRaw[s.axis];s.startRaw={...running};s.targetRaw={...running,[s.axis]:running[s.axis]+(s.axis==='B'&&bi++===8?d+shift:d)};running={...s.targetRaw};});wrong.finalTargetRaw=running;assert.throws(()=>B.validateBatch(wrong,1000,1,true),/12\/12\/12 then 6\/6\/6/);
 const tooLong=clone(q);while(tooLong.previewStages.length<=64)tooLong.previewStages.push(clone(tooLong.previewStages.at(-1)));assert.throws(()=>B.validateBatch(tooLong,1000,1,true),/scope limit/);
});
