const FTP=require('./ftp-two-pad.cjs');
function ftpRequest(){
 const q=request(),start=raw();q.scope=FTP.scope(false);q.rawBounds.Z.max=50;q.previewStages=[];let at={...start};
 function add(axis,value){const target={...at,[axis]:value};q.previewStages.push({axis,startRaw:at,targetRaw:target,speedFraction:axis==='B'?.05:1,expandedCommands:['synthetic'],...ev(),...(axis==='B'?{gapEvidence:{path:'/ftp/surface.json',sha256:hash},estimatedGapMm:.65,gapUncertaintyMm:.4}:{})});at=target;}
 add('B',-246);add('Z',45);add('X',101);add('Z',50);add('B',-252);add('Z',45);q.finalTargetRaw=at;
 const e=name=>({path:'/ftp/'+name,sha256:hash});
 q.ftpTargetEvidence=e('targets.json');q.ftpTargetRecord={schema:1,scope:'ftp-two-pad-commissioning-targets',boardId:'synthetic-cleaned-demo',sessionId,jvmStartMs:1,liveConfigurationSha256:hash,reviewedBy:'synthetic-test',reviewedMs:950,boardCleaned:true,padsAvailable:true,boardUnmovedSinceRegistration:true,provenance:'commissioning-provisional',precisionCalibrated:false,flowCalibrated:false,cadEvidence:e('board.kicad_pcb'),registrationEvidence:e('registration.json'),tipOffsetEvidence:e('offset.json'),surfaceEvidence:e('surface.json'),padAvailabilityImage:e('available.png'),cameraMinusTipXYMm:[5,-3],quantizationMm:0.01,surface:{rawZ:50,estimatedGapMm:.65,gapUncertaintyMm:.4},pads:[{padId:'R1.1',doseStageIndex:0,rawPose:{X:100,Y:200,Z:50,A:720}},{padId:'R1.2',doseStageIndex:4,rawPose:{X:101,Y:200,Z:50,A:720}}],padChecks:['R1','R16','R40'].map(reference=>({reference,padId:reference+'.1',reviewedAligned:true,reportEvidence:e(reference+'/report.json'),imageEvidence:e(reference+'/top.png')}))};return q;
}
function ftpSources(q){
 const t=q.ftpTargetRecord,files={},e=name=>({path:'/ftp/'+name,sha256:hash});
 const cameraReport=xy=>({status:'completed-contiguous-air-batch-awaiting-observation',controllerPositionVerified:true,uncertainCompletion:false,finishedAt:new Date(900).toISOString(),request:{jvmStartMs:1,liveConfigurationSha256:hash},afterImages:{top:{path:'top.png'}},afterQuerySnapshot:{nativePoses:{top:{x:xy[0],y:xy[1]}}}});
 const targets=Array.from({length:40},(_,i)=>[1,2].map(n=>({padId:`R${i+1}.${n}`,machineXYMm:[104+n,197]}))).flat();
 const reg={scope:'offline-fresh-ftp-two-fiducial-transform-with-third-point-check',acceptance:{passed:true},board:t.cadEvidence,session:{jvmStartMs:1,liveConfigurationSha256:hash},independentFID3Check:{residualMm:.01},measurements:{},resistorPadMachineXYTargets:targets};
 for(const fid of ['FID1','FID2','FID3']){reg.measurements[fid]={imageCenterErrorPx:1,report:e(fid+'/report.json'),image:e(fid+'/top.png')};files['/ftp/'+fid+'/report.json']=cameraReport([0,0]);}
 for(const c of t.padChecks)files[c.reportEvidence.path]=cameraReport(targets.find(p=>p.padId===c.padId).machineXYMm);
 const base={boardId:t.boardId,provenance:'commissioning-provisional',precisionCalibrated:false,jvmStartMs:1,liveConfigurationSha256:hash,reviewedBy:'synthetic-test',basisEvidence:e('basis.json')};
 files[t.registrationEvidence.path]=reg;files[t.tipOffsetEvidence.path]={...base,cameraMinusTipXYMm:t.cameraMinusTipXYMm};files[t.surfaceEvidence.path]={...base,surface:t.surface};files[q.ftpTargetEvidence.path]=clone(t);
 return {files,read:(e,json)=>{assert.match(e.sha256,/^[a-f0-9]{64}$/);if(json){assert.ok(files[e.path],e.path);return files[e.path];}return null;}};
}
