 function add(axis,value,dwell){if(value===at[axis])return;const target={...at,[axis]:value};q.previewStages.push({axis,startRaw:at,targetRaw:target,speedFraction:axis==='B'?.05:1,expandedCommands:['synthetic'],...ev(),...(axis==='B'?{gapEvidence:t.surfaceEvidence,estimatedGapMm:t.surface.estimatedGapMm+(t.surface.rawZ-at.Z),gapUncertaintyMm:t.surface.gapUncertaintyMm,dwellMilliseconds:dwell}:{})});at=target;}
