test('inline conditioner6 binds exact authored prefix without changing pad12/R3',()=>{const {q,t,anchor,context}=groupFixture(12,3,6);B.validateBatch(q,1000,1);assert.equal(B.reserveBatch(anchor,q,carry(),context).totalAbsoluteDegrees,355);const i=t.inlineConditioning.retractionStageIndex-1;assert.equal(q.previewStages[i].targetRaw.B-q.previewStages[i].startRaw.B,-6);assert.equal(q.previewStages[i].dwellMilliseconds,2000);assert.equal(q.previewStages.length,groupFixture(12,3,20).q.previewStages.length);for(const p of t.pads){assert.equal(p.doseStageIndices.length,2);for(const j of p.doseStageIndices)assert.equal(q.previewStages[j].targetRaw.B-q.previewStages[j].startRaw.B,-6);}const mismatch=clone(q);mismatch.ftpTargetRecord.inlineConditioning.experiment.conditioningDoseDegrees=20;assert.throws(()=>B.validateBatch(mismatch,1000,1),/prefix differs/);const bad=clone(q);bad.ftpTargetRecord.inlineConditioning.experiment.conditioningDoseDegrees=4;assert.throws(()=>B.validateBatch(bad,1000,1),/amounts/);});

test('explicit dummy finalwipe is only+X1.5 after R3 wait, within exact prefix and original clock',()=>{
 const {q,t,c,anchor,context}=groupFixture(12,3,6),x=t.inlineConditioning,i=x.retractionStageIndex+1,at=clone(q.previewStages[i].startRaw);x.experiment.conditioningFinalWipeMm=1.5;x.experiment.conditioningFinalWipeReviewed=true;
 const wipe={axis:'X',startRaw:at,targetRaw:{...at,X:at.X+1.5},speedFraction:1,expandedCommands:['synthetic'],...ev(),wipeReview:true,wipeReviewEvidence:q.clearanceReviewEvidence,estimatedGapMm:q.receivingProfile.estimatedGapMm,gapUncertaintyMm:q.receivingProfile.gapUncertaintyMm};q.previewStages[i].startRaw.X+=1.5;q.previewStages[i].targetRaw.X+=1.5;q.previewStages[i+1].startRaw.X+=1.5;q.previewStages.splice(i,0,wipe);x.prefixStageCount++;x.liftStageIndex++;for(const p of t.pads){p.restoreStageIndex++;p.retractStageIndex++;p.liftStageIndex++;p.doseStageIndices=p.doseStageIndices.map(v=>v+1);}c.finalIdleStageIndices=c.finalIdleStageIndices.map(v=>v+1);
 B.validateBatch(q,1000,1);assert.equal(B.reserveBatch(anchor,q,carry(),context).totalAbsoluteDegrees,355);assert.equal(B.stopDecision(q,wipe.startRaw,wipe,true),'stop-hold-position');assert.equal(B.stopDecision(q,wipe.targetRaw,q.previewStages[i+1],true),'reviewed-clearance-lift');
 const records=q.previewStages.slice(0,x.prefixStageCount).map((s,j)=>({...clone(s),index:j,verified:true,finishedAt:new Date(j===x.retractionStageIndex?1000:2000).toISOString()}));records[x.retractionStageIndex].dwell={requestedMilliseconds:500,actualElapsedMilliseconds:500,stopObserved:false};assert.equal(Inline.entry(q,16000,records),15000);assert.throws(()=>Inline.entry(q,16001,records),/15 seconds/);
 for(const edit of [v=>v.ftpTargetRecord.inlineConditioning.experiment.conditioningFinalWipeMm=-1.5,v=>v.ftpTargetRecord.inlineConditioning.experiment.conditioningFinalWipeReviewed=false,v=>v.previewStages[i].targetRaw.X+=.01,v=>v.previewStages[i].wipeReview=false]){const bad=clone(q);edit(bad);assert.throws(()=>B.validateBatch(bad,1000,1));}
});

test('conditioner12 is exactly two6 plus optional explicit restore3 with full charge',()=>{
 for(const restore of [0,3]){const {q,t,c,anchor,context}=groupFixture(12,3,12),x=t.inlineConditioning;
 if(restore){x.experiment.conditioningRestoreDegrees=3;const i=x.retractionStageIndex-2,old=q.previewStages[i],extra=clone(old);extra.targetRaw.B=extra.startRaw.B-3;extra.dwellMilliseconds=0;for(let j=i;j<q.previewStages.length;j++){q.previewStages[j].startRaw.B-=3;q.previewStages[j].targetRaw.B-=3;}q.previewStages.splice(i,0,extra);x.prefixStageCount++;x.retractionStageIndex++;x.liftStageIndex++;t.pads.forEach(p=>{p.restoreStageIndex++;p.doseStageIndices=p.doseStageIndices.map(v=>v+1);p.retractStageIndex++;p.liftStageIndex++;});c.finalIdleStageIndices=c.finalIdleStageIndices.map(v=>v+1);q.finalTargetRaw.B-=3;}
 B.validateBatch(q,1000,1);assert.equal(B.reserveBatch(anchor,q,carry(),context).totalAbsoluteDegrees,361+restore);
 const parts=q.previewStages.slice(x.retractionStageIndex-2,x.retractionStageIndex);assert.deepEqual(parts.map(s=>s.targetRaw.B-s.startRaw.B),[-6,-6]);assert.deepEqual(parts.map(s=>s.dwellMilliseconds),[0,2000]);
 for(const edit of [v=>v.previewStages[x.retractionStageIndex-2].dwellMilliseconds=2000,v=>v.ftpTargetRecord.inlineConditioning.experiment.conditioningDoseDegrees=6,v=>v.ftpTargetRecord.inlineConditioning.experiment.conditioningRestoreDegrees=2]){const bad=clone(q);edit(bad);assert.throws(()=>B.validateBatch(bad,1000,1));}
 }
});

test('cleanup100 reserves every+20 once, retains fault charge and verifies ordered completion',()=>{
 const q=cleanupFixture(20),t=q.ftpTargetRecord,p=t.pads[0],base=clone(q.previewStages[0]);t.cleanupSequence.protocol='positive-B-aspiration-series-lift-one-pad';t.cleanupSequence.retractDegrees=100;delete p.aspirationStageIndex;p.aspirationStageIndices=[0,1,2,3,4];p.liftStageIndex=5;let at=clone(q.expectedRaw);q.previewStages=[];for(let i=0;i<5;i++){const target={...at,B:at.B+20};q.previewStages.push({...clone(base),startRaw:at,targetRaw:target});at=target;}q.previewStages.push({axis:'Z',startRaw:at,targetRaw:{...at,Z:q.xyClearanceRawZ},speedFraction:1,expandedCommands:['synthetic'],...ev()});q.finalTargetRaw=clone(q.previewStages.at(-1).targetRaw);q.rawBounds.B.max=q.finalTargetRaw.B;
 B.validateBatch(q,1000,1);let l=B.reserveBatch(ledger(),q,carry());assert.equal(l.totalAbsoluteDegrees,100);assert.equal(B.finishBatch(l,q,false).totalAbsoluteDegrees,100);assert.throws(()=>B.markBatchStep(l,q,1,q.previewStages[1].targetRaw.B));assert.equal(B.stopDecision(q,q.previewStages[0].targetRaw,q.previewStages[1],true),'stop-hold-position');assert.equal(B.stopDecision(q,q.previewStages[4].targetRaw,q.previewStages[5],true),'reviewed-clearance-lift');for(let i=0;i<5;i++)l=B.markBatchStep(l,q,i,q.previewStages[i].targetRaw.B);l=B.finishBatch(l,q,true);assert.equal(l.lastVerifiedB,-140);assert.equal(l.entries.length,5);assert.throws(()=>B.reserveBatch(l,q,carry()));
});
